  <link href="https://unpkg.com/maplibre-gl@4.2.0/dist/maplibre-gl.css" rel="stylesheet" />
  <style>
    body { margin:0; padding:0; }
    #map { position:absolute; top:0; bottom:0; width:100%; }
  </style>
</head>
<body>
<div id="map"></div>
<script>
  const map = new maplibregl.Map({
    container: 'map',
    style: 'https://demotiles.maplibre.org/style.json',
    center: [13.4, 52.5],
    zoom: 12,
    pitch: 70,
    bearing: 0,
    antialias: true
  });

  map.on('load', () => {
    // 1️⃣ DEM source
    map.addSource('terrain-dem', {
      type: 'raster-dem',
      url: 'https://tiles.mapterhorn.com/tilejson.json',
      tileSize: 256,
      maxzoom: 12,
      encoding: 'terrarium'
    });

    // 2️⃣ Enable terrain
    map.setTerrain({ source: 'terrain-dem', exaggeration: 1 });

    // 3️⃣ Add sky + fog
    map.setSky({
      'sky-color': '#87CEEB',
      'horizon-color': '#ffffff',
      'sky-horizon-blend': 0.5,
      'fog-color': '#c0d8ff',
      'horizon-fog-blend': 0.4,
      'fog-ground-blend': 0.2
    });

    // 4️⃣ (optional) make background transparent
    const bgId = map.getStyle().layers.find(l => l.type === 'background')?.id;
    if (bgId) map.setPaintProperty(bgId, 'background-color', 'rgba(0,0,0,0)');
